        x, y = to_xy(p if not isinstance(p, dict) else p)
        if 0 <= x < w and 0 <= y < h:
            obstacles.add((x, y))

    resources = []
    for r in observation.get("resources", []) or []:
        x, y = to_xy(r)
        if 0 <= x < w and 0 <= y < h:
            resources.append((x, y))

